import React from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";
import { FPS, G, HEAD, INK, Label, Logo, OUT, TXT, cl, hs, k, lin, pop, Spin } from "./shared";
import CAPS from "./meiaCaps.json";

// GIRO MONEY — Vídeo 2: "Consórcio de meia parcela" (roteiro do o diretor, 30/10). Só motion, cinco cenas do roteiro:
// parcela partindo em 50% → bonequinhos no cofre verde → meia parcela e sorteios → colunas sim/não → ampulheta e o
// passo verde + CTA. Voz o locutor (v3) 66,5 s sem silêncio morto; tempos = palavra da voz cortada. Identidade do Instagram:
// preto esverdeado e branco esverdeado, verde #13F25E, condensada itálica com tarja verde. Legenda palavra por palavra.
// Transições deste vídeo (diferentes da fala e da moto): divisão ao meio, virada 3D, aperto, giro e listras.

export const GME_FRAMES = Math.round(68.0 * FPS);
const D = 0.3;
const BK = "#050806";
const PALE = "#EDF6EF";
const GREY = "#8C968F";
const RED = "#E5484D";

type Tin = "none" | "split" | "flip" | "squeeze" | "spin" | "stripes";
const ease = Easing.bezier(0.33, 0, 0.2, 1);
const tinStyle = (type: Tin, p: number): React.CSSProperties => {
  const e = ease(Math.min(1, Math.max(0, p)));
  if (type === "split") return { clipPath: `inset(${((1 - e) * 50).toFixed(2)}% 0 ${((1 - e) * 50).toFixed(2)}% 0)` };
  if (type === "flip") return { transform: `perspective(1600px) rotateY(${((1 - e) * 80).toFixed(1)}deg)`, opacity: Math.min(1, e * 2), transformOrigin: "0% 50%" };
  if (type === "squeeze") return { transform: `scaleX(${(0.05 + 0.95 * e).toFixed(4)})`, opacity: Math.min(1, e * 3) };
  if (type === "spin") return { transform: `rotate(${((1 - e) * -12).toFixed(2)}deg) scale(${(0.7 + 0.3 * e).toFixed(4)})`, opacity: Math.min(1, e * 2) };
  if (type === "stripes") {
    const w = (e * 10).toFixed(2);
    const m = `repeating-linear-gradient(60deg, #000 0px, #000 ${w}%, transparent ${w}%, transparent 10%)`;
    return { WebkitMaskImage: m, maskImage: m };
  }
  return {};
};

const Bg: React.FC<{ t: number; pale?: boolean }> = ({ t, pale }) => (
  <AbsoluteFill style={{ background: `radial-gradient(ellipse 90% 60% at ${(50 + Math.sin(t * 0.8) * 24).toFixed(1)}% ${(42 + Math.cos(t * 0.6) * 12).toFixed(1)}%, ${pale ? "#FFFFFF" : "#10301C"} 0%, ${pale ? "#DCEDE1" : BK} 80%)` }} />
);
// câmera: aproxima bem e desliza durante a cena (o motion em fundo liso mede pouco movimento sem isso)
const Cam: React.FC<{ t: number; a: number; b: number; children: React.ReactNode; from?: number; to?: number }> = ({ t, a, b, children, from = 0.94, to = 1.04 }) => {
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.inOut(Easing.quad) });
  const z = from + (to - from) * p + (to >= from ? 0.06 : -0.06) * p;
  return (
    <AbsoluteFill style={{ transform: `translate(${(Math.sin(t * 0.9) * 34 + (p - 0.5) * 50).toFixed(1)}px, ${(Math.cos(t * 0.7) * 22).toFixed(1)}px) rotate(${(Math.sin(t * 0.5) * 1.2).toFixed(2)}deg) scale(${z.toFixed(4)})`, transformOrigin: "50% 45%" }}>{children}</AbsoluteFill>
  );
};
type W = [string, number, boolean?];
const Title: React.FC<{ t: number; items: W[]; size?: number; top?: number; dark?: boolean }> = ({ t, items, size = 104, top = 440, dark }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.22, rowGap: size * 0.08 }}>
    {items.map(([w, at, tag], i) => {
      const e = interpolate(t, [at, at + 0.28], [0, 1], { ...cl, easing: OUT });
      return (
        <span key={i} style={{ ...hs(size, tag ? INK : dark ? INK : "#FFFFFF"), display: "inline-block", opacity: e, transform: `translateY(${((1 - e) * size * 0.4).toFixed(1)}px)`, background: tag ? G : undefined, padding: tag ? `${size * 0.03}px ${size * 0.14}px ${size * 0.07}px` : undefined, borderRadius: tag ? size * 0.1 : undefined }}>
          {w}
        </span>
      );
    })}
  </div>
);
const mid: React.CSSProperties = { position: "absolute", left: 0, right: 0, display: "flex", justifyContent: "center", alignItems: "center" };

// legenda grande, palavra por palavra, no mesmo lugar
type Cap = { a: number; b: number; w: [string, number, boolean][] };
const Captions: React.FC<{ t: number; pale: boolean }> = ({ t, pale }) => {
  const caps = CAPS as Cap[];
  let idx = -1;
  for (let i = 0; i < caps.length; i++) if (t >= caps[i].a - 0.05) idx = i;
  if (idx < 0) return null;
  const c = caps[idx];
  const next = caps[idx + 1];
  if (t >= (next ? next.a - 0.05 : 99)) return null;
  return (
    <div style={{ position: "absolute", left: 110, right: 110, top: 1300, display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: 20, rowGap: 6 }}>
      {c.w.map(([w, at, key], i) => {
        const e = interpolate(t, [at - 0.04, at + 0.16], [0, 1], { ...cl, easing: Easing.out(Easing.back(2)) });
        return (
          <span key={i} style={{ fontFamily: HEAD, fontStyle: "italic", fontWeight: 800, fontSize: 90, lineHeight: 1.05, textTransform: "uppercase", whiteSpace: "nowrap", color: key ? INK : pale ? INK : "#FFFFFF", background: key ? G : undefined, borderRadius: 12, padding: key ? "0 14px 4px" : undefined, opacity: t >= at - 0.04 ? Math.min(1, e * 2) : 0, transform: `scale(${(0.6 + 0.4 * e).toFixed(3)})`, display: "inline-block", textShadow: key || pale ? "none" : "0 4px 16px rgba(0,0,0,0.6)" }}>
            {w.replace(/[.,?]$/, "")}
          </span>
        );
      })}
    </div>
  );
};

// ─── peças ───
const Person: React.FC<{ s: number; c?: string; glow?: boolean }> = ({ s, c = PALE, glow }) => (
  <svg width={s} height={s * 1.6} viewBox="0 0 60 96" style={{ overflow: "visible", filter: glow ? "drop-shadow(0 0 14px rgba(19,242,94,0.8))" : undefined }}>
    <circle cx={30} cy={16} r={14} fill={c} />
    <path d="M8 96 L8 52 Q8 34 30 34 Q52 34 52 52 L52 96 Z" fill={c} />
  </svg>
);
const Safe: React.FC<{ s: number; t: number; open?: number }> = ({ s, t, open = 0 }) => (
  <div style={{ position: "relative", width: s, height: s }}>
    <div style={{ position: "absolute", inset: 0, borderRadius: s * 0.12, background: G, boxShadow: "0 30px 70px rgba(0,0,0,0.5), inset 0 -14px 0 #0A9E3F" }} />
    <div style={{ position: "absolute", left: s * 0.14, top: s * 0.14, width: s * 0.72, height: s * 0.72, borderRadius: s * 0.08, background: "#0DBF4B", transform: `perspective(900px) rotateY(${(-open * 70).toFixed(1)}deg)`, transformOrigin: "0% 50%", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: s * 0.42, height: s * 0.42, borderRadius: "50%", background: INK, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Spin t={t * 0.6} s={s * 0.36} />
      </div>
    </div>
    {[0.3, 0.7].map((y) => (
      <div key={y} style={{ position: "absolute", left: -s * 0.04, top: s * y - s * 0.05, width: s * 0.08, height: s * 0.1, borderRadius: 6, background: "#0A9E3F" }} />
    ))}
  </div>
);
const Coin: React.FC<{ s: number; half?: boolean }> = ({ s, half }) => (
  <svg width={s} height={s} viewBox="0 0 40 40">
    <circle cx={20} cy={20} r={18} fill={half ? "rgba(19,242,94,0.2)" : G} stroke={INK} strokeWidth={3} />
    {half ? <path d="M20 2 A18 18 0 0 0 20 38 Z" fill={G} /> : null}
    <text x={20} y={26} textAnchor="middle" fontSize={15} fontWeight={800} fill={INK} fontFamily="sans-serif">R$</text>
  </svg>
);
const Ball: React.FC<{ s: number; n: string; c?: string }> = ({ s, n, c = "#FFFFFF" }) => (
  <div style={{ width: s, height: s, borderRadius: "50%", background: `radial-gradient(circle at 35% 30%, #FFFFFF 0%, ${c} 55%, #B9C6BD 100%)`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 10px 24px rgba(0,0,0,0.35)" }}>
    <div style={hs(s * 0.5, INK)}>{n}</div>
  </div>
);
const Check: React.FC<{ s: number; no?: boolean }> = ({ s, no }) => (
  <div style={{ width: s, height: s, borderRadius: s * 0.25, background: no ? RED : G, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
    <svg width={s * 0.62} height={s * 0.62} viewBox="0 0 24 24" fill="none" stroke={no ? "#FFFFFF" : INK} strokeWidth={3.6} strokeLinecap="round" strokeLinejoin="round">
      {no ? <path d="M6 6l12 12M18 6L6 18" /> : <path d="M4.5 12.5l5 5L19.5 7" />}
    </svg>
  </div>
);
const Hourglass: React.FC<{ s: number; p: number }> = ({ s, p }) => (
  <svg width={s} height={s * 1.4} viewBox="0 0 100 140">
    <rect x={10} y={4} width={80} height={10} rx={4} fill={PALE} />
    <rect x={10} y={126} width={80} height={10} rx={4} fill={PALE} />
    <path d="M20 14 L80 14 Q80 50 54 70 Q80 90 80 126 L20 126 Q20 90 46 70 Q20 50 20 14 Z" fill="none" stroke={PALE} strokeWidth={5} />
    {/* areia de cima diminuindo, de baixo crescendo */}
    <path d={`M${26 + p * 20} ${20 + p * 40} L${74 - p * 20} ${20 + p * 40} Q${72 - p * 20} ${48 + p * 10} 50 66 Q${28 + p * 20} ${48 + p * 10} ${26 + p * 20} ${20 + p * 40} Z`} fill={G} opacity={1 - p * 0.9} />
    <path d={`M24 122 L76 122 L${76 - (1 - p) * 26} ${122 - p * 34} L${24 + (1 - p) * 26} ${122 - p * 34} Z`} fill={G} />
    <line x1={50} y1={66} x2={50} y2={120} stroke={G} strokeWidth={2} strokeDasharray="3 4" />
  </svg>
);

// ─── cenas (tempo da voz cortada) ───
type Scene = { a: number; tin: Tin; pale?: boolean; render: (t: number, a: number, b: number) => React.ReactNode };

const SCENES: Scene[] = [
  // 1 — a parcela inteira se parte ao meio: 50% em verde
  {
    a: 0,
    tin: "none",
    render: (t, a, b) => {
      const sp = interpolate(t, [3.03, 3.6], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.3)) });
      const half = (side: number) => (
        <div style={{ position: "absolute", left: side < 0 ? 0 : "50%", top: 0, width: "50%", height: "100%", overflow: "hidden", transform: `translateX(${(side * sp * 90).toFixed(0)}px) rotate(${(side * sp * 6).toFixed(2)}deg)`, opacity: side > 0 ? 1 - sp * 0.65 : 1 }}>
          <div style={{ position: "absolute", left: side < 0 ? 0 : "-100%", top: 0, width: "200%", height: "100%", borderRadius: 40, background: "#FFFFFF", padding: "36px 44px", boxSizing: "border-box" }}>
            <Label size={28} color={GREY}>
              Sua parcela
            </Label>
            <div style={{ ...hs(150, INK), marginTop: 10 }}>PARCELA</div>
            <div style={{ height: 30, borderRadius: 15, background: "#DCEDE1", marginTop: 26, overflow: "hidden" }}>
              <div style={{ width: "100%", height: "100%", background: side < 0 ? G : "#C9D6CD" }} />
            </div>
          </div>
        </div>
      );
      const ent = interpolate(t, [0, 0.5], [0, 1], { ...cl, easing: OUT });
      return (
        <>
          <Bg t={t} />
          <Cam t={t} a={a} b={b} from={1.1} to={1.0}>
            <div style={{ position: "absolute", left: 140, top: 560, width: 800, height: 320, transform: `translateY(${((1 - ent) * 500).toFixed(0)}px) rotate(${((1 - ent) * -8).toFixed(1)}deg)`, opacity: ent }}>
              {half(-1)}
              {half(1)}
              {sp > 0.02 ? <div style={{ position: "absolute", left: "50%", top: -40, bottom: -40, width: 6, background: G, opacity: 1 - sp, transform: "translateX(-3px)", boxShadow: "0 0 20px rgba(19,242,94,0.9)" }} /> : null}
            </div>
            <div style={{ ...mid, top: 930, transform: `scale(${pop(t, 3.1, 0.45).toFixed(3)})`, opacity: t >= 3.1 ? 1 : 0 }}>
              <div style={{ ...hs(230, INK), background: G, borderRadius: 30, padding: "4px 40px 14px", boxShadow: "0 0 40px rgba(19,242,94,0.5)" }}>50%</div>
            </div>
          </Cam>
        </>
      );
    },
  },
  // 2a — um grupo de sócios em volta do cofre verde
  {
    a: 6.6,
    tin: "split",
    render: (t, a, b) => (
      <>
        <Bg t={t} />
        <Cam t={t} a={a} b={b}>
          <div style={{ ...mid, top: 760, transform: `scale(${pop(t, 7.0, 0.45).toFixed(3)})` }}>
            <Safe s={360} t={t} />
          </div>
          {[0, 1, 2, 3, 4, 5].map((i) => {
            const ang = (i / 6) * Math.PI * 2 - Math.PI / 2 + t * 0.15;
            const at = 8.38 + i * 0.12;
            return (
              <div key={i} style={{ position: "absolute", left: 540 + Math.cos(ang) * 340 - 42, top: 920 + Math.sin(ang) * 270 - 67, opacity: t >= at ? 1 : 0, transform: `scale(${pop(t, at, 0.35).toFixed(3)})` }}>
                <Person s={84} />
              </div>
            );
          })}
        </Cam>
      </>
    ),
  },
  // 2b — cada um paga a parcela; sem juros de banco, só a taxa de administração
  {
    a: 10.8,
    tin: "flip",
    pale: true,
    render: (t, a, b) => (
      <>
        <Bg t={t} pale />
        <Cam t={t} a={a} b={b}>
          <div style={{ ...mid, top: 640 }}>
            <Safe s={300} t={t} />
          </div>
          {[0, 1, 2, 3].map((i) => {
            const x = 150 + i * 260;
            const at = 11.3 + i * 0.18;
            const fly = interpolate(t, [at + 0.2, at + 0.7], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
            return (
              <React.Fragment key={i}>
                <div style={{ position: "absolute", left: x - 30, top: 1060 }}>
                  <Person s={60} c={INK} />
                </div>
                <div style={{ position: "absolute", left: x - 30 + (540 - x) * fly, top: 1000 - fly * 220, opacity: t >= at && fly < 1 ? 1 : 0 }}>
                  <Coin s={60} />
                </div>
              </React.Fragment>
            );
          })}
          {/* sem juros de banco */}
          <div style={{ position: "absolute", left: 120, top: 440, display: "flex", alignItems: "center", gap: 16, opacity: k(t, 12.96, 0.3), transform: `translateY(${((1 - k(t, 12.96, 0.3)) * 30).toFixed(0)}px)` }}>
            <div style={{ position: "relative", ...hs(70, INK), background: "#FFFFFF", borderRadius: 16, padding: "4px 22px 10px" }}>
              JUROS
              <div style={{ position: "absolute", left: 10, right: 10, top: "50%", height: 8, background: RED, borderRadius: 4, transform: `scaleX(${k(t, 13.4, 0.3).toFixed(3)})`, transformOrigin: "0 50%" }} />
            </div>
          </div>
          <div style={{ position: "absolute", right: 120, top: 440, opacity: k(t, 14.66, 0.3), transform: `translateY(${((1 - k(t, 14.66, 0.3)) * 30).toFixed(0)}px)` }}>
            <div style={{ ...hs(52, INK), background: G, borderRadius: 14, padding: "8px 20px 12px", textAlign: "center", lineHeight: 0.95 }}>
              TAXA DE
              <br />
              ADMINISTRAÇÃO
            </div>
          </div>
        </Cam>
      </>
    ),
  },
  // 2c — todo mês tem contemplado: sorteio pela Loteria Federal ou lance
  {
    a: 16.1,
    tin: "squeeze",
    render: (t, a, b) => {
      const lance = t >= 20.2;
      return (
        <>
          <Bg t={t} />
          <Cam t={t} a={a} b={b}>
            <div style={{ ...mid, top: 560, gap: 26 }}>
              {[0, 1, 2, 3, 4].map((i) => {
                const at = 18.4 + i * 0.12;
                const n = t < at + 0.5 ? String(Math.floor((t * 37 + i * 13) % 10)) : String([3, 7, 1, 9, 4][i]);
                return (
                  <div key={i} style={{ opacity: t >= at ? 1 : 0, transform: `translateY(${((1 - pop(t, at, 0.4)) * -200).toFixed(0)}px)` }}>
                    <Ball s={130} n={n} />
                  </div>
                );
              })}
            </div>
            <div style={{ ...mid, top: 740, opacity: k(t, 19.0, 0.3) }}>
              <Label size={30} color={GREY}>
                Loteria Federal
              </Label>
            </div>
            {/* os sócios: um acende (contemplado) */}
            <div style={{ ...mid, top: 880, gap: 40, alignItems: "flex-end" }}>
              {[0, 1, 2, 3, 4].map((i) => {
                const win = i === 2 && t >= 17.46;
                const bid = i === 4 && lance;
                return (
                  <div key={i} style={{ position: "relative", transform: `translateY(${(win ? -20 * pop(t, 17.46, 0.4) : 0).toFixed(1)}px)` }}>
                    <Person s={92} c={win ? G : PALE} glow={win} />
                    {bid ? (
                      <div style={{ position: "absolute", left: -20, top: -110, ...hs(44, INK), background: "#FFFFFF", borderRadius: 10, padding: "4px 14px 8px", transform: `scale(${pop(t, 20.3, 0.35).toFixed(3)}) rotate(-6deg)` }}>LANCE</div>
                    ) : null}
                  </div>
                );
              })}
            </div>
            {/* média do grupo */}
            <div style={{ position: "absolute", left: 160, right: 160, top: 1200, height: 14, borderRadius: 7, background: "rgba(237,246,239,0.15)", opacity: k(t, 21.1, 0.3) }}>
              <div style={{ width: `${(lin(t, 21.2, 22.0) * 55).toFixed(1)}%`, height: "100%", borderRadius: 7, background: G }} />
            </div>
          </Cam>
        </>
      );
    },
  },
  // 3a — meia parcela: paga 50% e participa de todos os sorteios
  {
    a: 22.7,
    tin: "spin",
    pale: true,
    render: (t, a, b) => (
      <>
        <Bg t={t} pale />
        <Cam t={t} a={a} b={b}>
          <div style={{ ...mid, top: 640, gap: 60, alignItems: "flex-end" }}>
            <Person s={130} c={INK} />
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
              <div style={{ transform: `scale(${pop(t, 24.3, 0.4).toFixed(3)})` }}>
                <Coin s={170} half />
              </div>
              <div style={{ ...hs(80, INK), opacity: t >= 25.23 ? 1 : 0, transform: `scale(${pop(t, 25.23, 0.35).toFixed(3)})` }}>50%</div>
            </div>
          </div>
          {/* participa de todos os sorteios: bilhetes do mês entrando, todos marcados */}
          <div style={{ ...mid, top: 1060, gap: 18 }}>
            {["JAN", "FEV", "MAR", "ABR", "MAI"].map((m, i) => {
              const at = 27.47 + i * 0.22;
              return (
                <div key={m} style={{ width: 140, height: 120, borderRadius: 18, background: "#FFFFFF", border: `4px solid ${INK}`, boxSizing: "border-box", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, opacity: t >= at ? 1 : 0, transform: `translateY(${((1 - pop(t, at, 0.35)) * 60).toFixed(0)}px)` }}>
                  <div style={hs(40, INK)}>{m}</div>
                  <Check s={36} />
                </div>
              );
            })}
          </div>
        </Cam>
      </>
    ),
  },
  // 3b — depois da contemplação: crédito na mão, a parcela volta ao valor integral
  {
    a: 29.9,
    tin: "stripes",
    render: (t, a, b) => {
      const fill = interpolate(t, [33.3, 34.3], [0.5, 1], { ...cl, easing: Easing.inOut(Easing.quad) });
      return (
        <>
          <Bg t={t} />
          <Cam t={t} a={a} b={b}>
            <div style={{ ...mid, top: 460 }}>
              <div style={{ background: "#FFFFFF", borderRadius: 30, padding: "24px 40px", display: "flex", alignItems: "center", gap: 24, transform: `scale(${pop(t, 31.3, 0.45).toFixed(3)}) rotate(-3deg)`, boxShadow: "0 30px 70px rgba(0,0,0,0.5)" }}>
                <div style={{ width: 90, height: 64, borderRadius: 12, background: G }} />
                <div>
                  <Label size={24} color={GREY}>
                    Carta de crédito
                  </Label>
                  <div style={hs(70, INK)}>CONTEMPLADO</div>
                </div>
              </div>
            </div>
            <div style={{ ...mid, top: 740 }}>
              <Person s={120} c={G} glow />
            </div>
            <div style={{ position: "absolute", left: 140, right: 140, top: 1020 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
                <Label size={26} color={PALE}>
                  Parcela
                </Label>
                <div style={hs(56, G)}>{`${Math.round(fill * 100)}%`}</div>
              </div>
              <div style={{ height: 46, borderRadius: 23, background: "rgba(237,246,239,0.15)", overflow: "hidden" }}>
                <div style={{ width: `${(fill * 100).toFixed(1)}%`, height: "100%", background: G, borderRadius: 23 }} />
              </div>
            </div>
          </Cam>
        </>
      );
    },
  },
  // 4a — duas colunas: para quem é (sim) e para quem não é (não)
  {
    a: 34.9,
    tin: "split",
    pale: true,
    render: (t, a, b) => {
      const SIM: [number, string][] = [
        [38.05, "Paga aluguel"],
        [39.01, "Já tem financiamento"],
        [40.59, "Quer investir"],
      ];
      const col = (no: boolean, at: number, title: string, items: [number, string][]) => (
        <div style={{ width: 440, borderRadius: 30, background: "#FFFFFF", overflow: "hidden", boxShadow: "0 24px 60px rgba(0,0,0,0.18)", opacity: t >= at ? 1 : 0, transform: `translateY(${((1 - pop(t, at, 0.4)) * 120).toFixed(0)}px)` }}>
          <div style={{ background: no ? RED : G, padding: "14px 0 18px", textAlign: "center", ...hs(74, no ? "#FFFFFF" : INK) }}>{title}</div>
