export const GiroMeia: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const end = GME_FRAMES / FPS;
  let pale = false;
  for (const s of SCENES) if (t >= s.a) pale = !!s.pale;
  return (
    <AbsoluteFill style={{ background: BK }}>
      {SCENES.map((s, i) => {
        const next = SCENES[i + 1];
        const b = next ? next.a : end;
        const vis0 = s.tin === "none" ? s.a : s.a - D / 2;
        const vis1 = next ? b + D / 2 : end;
        if (t < vis0 || t >= vis1) return null;
        const p = s.tin === "none" ? 1 : (t - (s.a - D / 2)) / D;
        return (
          <AbsoluteFill key={i} style={p < 1 ? tinStyle(s.tin, p) : undefined}>
            {s.render(t, s.a, b)}
          </AbsoluteFill>
        );
      })}
      <Captions t={t} pale={pale} />
      <AbsoluteFill style={{ background: "#000", opacity: interpolate(t, [end - 0.4, end], [0, 1], cl) }} />
    </AbsoluteFill>
  );
};
