export const { fontFamily: HEAD } = loadHead("italic", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: TXT } = loadTxt("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const FPS = 30;
export const G = "#13F25E";
