export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const BACK = Easing.out(Easing.back(1.5));
export const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const slam = (t: number, at: number, d = 0.24): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.5 - 0.5 * e).toFixed(3)})` };
};
export const rise = (t: number, at: number, dy = 60, d = 0.45): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: e, transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
export const hs = (size: number, color: string, weight = 800): React.CSSProperties => ({ fontFamily: HEAD, fontStyle: "italic", fontWeight: weight, fontSize: size, lineHeight: 1, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "0.01em" });
