export const Cam: React.FC<{ t: number; a: number; b: number; children: React.ReactNode }> = ({ t, a, b, children }) => {
  if (t < a || t >= b) return null;
  return <AbsoluteFill style={{ transform: `translate(${(Math.sin(t * 1.3) * 13).toFixed(1)}px, ${(Math.cos(t * 1.1) * 9).toFixed(1)}px) scale(${(0.92 + 0.08 * lin(t, a, Math.min(b, a + 7))).toFixed(4)})`, transformOrigin: "50% 36%" }}>{children}</AbsoluteFill>;
