export const Cut: React.FC<{ t: number; at: number; i: number; pale?: boolean; d?: number }> = ({ t, at, i, pale, d = 0.18 }) => {
  if (t < at - d || t > at + d) return null;
  const dir = i % 2 ? -1 : 1;
