  return <div style={{ position: "absolute", left: 540 - 900, top: -200, width: 1800, height: 2320, background: pale ? PALE : BK, transform: `translateX(${x.toFixed(0)}px) skewX(${-14 * dir}deg)`, boxShadow: `${16 * dir}px 0 0 ${G}, ${-16 * dir}px 0 0 ${G}` }} />;
};
